	A.remotes = {}
	function A.netRemote(name)
	    local r = A.remotes[name]
	    if r and r.Parent then return r end
	    local pk = ReplicatedStorage:FindFirstChild("Packages")
	    local net = pk and pk:FindFirstChild("Net")
	    r = net and net:FindFirstChild(name) or nil
	    A.remotes[name] = r
	    return r
	end
	
	function A.fireLoop(flag, name, delay, label, ...)
	    local args = table.pack(...)
	    task.spawn(function()
	        local warned = false
	        while W.gui.Parent do
	            if S[flag] then
	                local ev = A.netRemote(name)
	                if ev then
	                    pcall(function() ev:FireServer(table.unpack(args, 1, args.n)) end)
	                    warned = false
	                elseif not warned then
	                    warned = true
	                    A.toast(label .. " remote not found", C.red)
	                end
	            end
	            task.wait(delay)
	        end
	    end)
	end
	
	
	
