	            local full = XP and XP.cur and XP.max and XP.max > 0 and XP.cur >= XP.max
	            if full then
	                local key = tostring(XP.level) .. "|" .. tostring(XP.max)
	                if firedFor ~= key or os.clock() - firedAt > UPGRADE_RETRY then
	                    local ev = A.netRemote(UPGRADE_RE)
	                    if ev then
	                        pcall(function() ev:FireServer(UPGRADE_ARG) end)
	                        firedAt, firedFor, warned = os.clock(), key, false
