	local Egg = { rows = {}, MIN_LEN = (math.floor(((((1+4)+(2+3))+((31+14)-(78-53)))+(((84-45)-(4*2))+((1+0)+(1+0))))/9)), MAX_ROWS = ((math.floor((((27+37)-(24-4))-((68-50)-(7*2)))/4))+(((math.floor((5+75)/5))-(math.floor((1+4)/5)))*(((88-61)-(90-64))+((1+0)+0)))) }
	
