	    if not Egg.dirty and d:IsA("Model") and Egg.isEgg(d) then Egg.dirty = true end
	end)
	workspace.DescendantRemoving:Connect(function(d)
	    if Egg.rows[d] then Egg.dirty = true end
	end)
	
	function Egg.tick()
	    local ch = player.Character
