	    for m, row in pairs(Egg.rows) do
	        if m.Parent then
	            local left = Egg.timeLeft(m)
	            row.time.Text = left and Egg.fmt(left) or "no timer"
	            row.time.TextColor3 = left and C.red or C.dim
	            local p = Egg.pos(m)
