	function Isle.go(isl)
	    local cf, size = Isle.box(isl)
	    if not cf then A.toast("Can't reach that island", C.red) return end
	    Isle.fly({ name = Isle.name(isl), inst = isl, cf = cf, size = size })
	end
	
	
