	    end)
	end
	
	
	
	
	A.showPage("farm")
	A.intro(function()
	    A.setWindow(true)
	    A.toast(A.greeting() .. "  ·  RightShift to hide", C.violet)
	end)
	print("[INFIN] Egg Farm v3.2 loaded")
end)()
